import type { VariableConfig } from '../../Variable'

/**
 * Configuration type for HTML variables
 * @interface
 */
export type HtmlVariableType<Type extends string = string, Default extends Type = Type> = VariableConfig<
    Type,
    Default
> & {
    defaultHTML?: string
}

/**
 * A CatalogItem variable for an HTML field.
 *
 * @see https://docs.servicenow.com/csh?topicname=variable-types.html&version=latest
 *
 * @param config - Configuration for the HTML variable including:
 *   * **question** - Question text displayed to the user
 *   * **defaultHTML**? - Default HTML content for the variable
 *   * And all other properties from the base Variable type
 * @group ServiceCatalog/Variables
 */
export function HtmlVariable(config: HtmlVariableType) {
    return config
}
